mapper.select:
select * from (
select t_classroom.*, zyxx.zysl occupy_count, capacity - ifnull(zyxx.zysl, 0) as left_count
    from t_classroom
    left join (
        select classroom_id, count(1) as zysl
        from t_classroom_occupy
        group by t_classroom_occupy.classroom_id
    ) zyxx on t_classroom.id = zyxx.classroom_id
) as t

    ${ew.getSqlSegment()}
